with exploded as (select id, customer_id, created_at, elem.product_id, elem.price, elem.promo from carts lateral view outer explode(items) e as elem) select date_trunc('day', created_at) as activity_day, case when product_id >= 9 then 'LARGE' else 'SMALL' end as product_id_tier, date_trunc('hour', created_at) as hour_window, max(product_id) filter (where promo = 'SPRING10') as spring10_max_product_id, round(avg(product_id), 2) as avg_product_id, count(*) filter (where promo = 'VIP') as vip_rows, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as duration_min, sort_array(collect_set(promo)) as promo_list, grouping(date_trunc('day', created_at)) as grouping_id from exploded group by rollup (date_trunc('day', created_at), case when product_id >= 9 then 'LARGE' else 'SMALL' end, date_trunc('hour', created_at)) order by hour_window;
